import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_equally():
    groups = {"small": [{"flagged": True}], "large": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 7), (6, 9)])
def test_flags_in_window(days, expected):
    assert flags_in_window([2, 3, 4], days) == expected


def test_parse_transcript_log_flags_whitespace_and_skips():
    lines = ["", "  \t\n", "  # comment, with, commas", " a , 3 , 1 ", "b, 4, 0", "c, -5, "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": 4, "flagged": False},
        {"id": "c", "day": -5, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,0"])
def test_parse_transcript_log_errors_include_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", "  # ignored", "ok,1,1", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    first = {"id": "b", "day": 4, "flagged": True}
    last = {"id": "b", "day": 2, "flagged": False}
    same_day = {"id": "a", "day": 2, "flagged": True}
    earlier_day = {"id": "c", "day": 1, "flagged": None}
    assert dedupe_transcripts([first, earlier_day, last, same_day]) == [earlier_day, same_day, last]


def test_daily_flag_counts_fills_gaps_and_respects_inclusive_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,2,", "f,4,1", "g,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], 1, 2) == [0, 0]


def test_monitor_summary_uses_calendar_days_and_ignores_empty_groups():
    groups = {
        "first": parse_transcript_log(["a,1,1"]),
        "second": parse_transcript_log(["b,3,1", "c,5,0"]),
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_breaks_ties_by_name_and_excludes_empty_groups():
    groups = {"z": [{"flagged": False}], "b": [{"flagged": True}], "a": [{"flagged": True}], "empty": []}
    assert top_flagged_groups(groups, 2) == ["a", "b"]
    assert top_flagged_groups(groups, 10) == ["a", "b", "z"]


def test_flag_rate_by_group_includes_empty_groups_and_sorts_keys():
    groups = {"z": [{"flagged": True}], "b": [], "a": [{"flagged": None}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", None), ("z", 1.0)]


@pytest.mark.parametrize(
    ("counts", "expected"),
    [([], 0), ([0, -1], 0), ([1, 1, 0, 2, 2, 2, -1, 1], 3)],
)
def test_longest_flag_streak_counts_only_consecutive_positive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
